{
  "name": "CI - Orchestrator",
  "on": {
    "pull_request": {
      "branches": [
        "develop",
        "main"
      ],
      "types": [
        "opened",
        "synchronize",
        "reopened",
        "edited",
        "ready_for_review"
      ]
    },
    "push": {}
  },
  "permissions": {
    "contents": "read"
  },
  "concurrency": {
    "group": "ci-${{ github.workflow }}-${{ github.event.pull_request.number || ((github.event_name == 'push' && (github.ref_name == 'develop' || github.ref_name == 'main')) && format('{0}-{1}', github.ref, github.sha)) || github.ref }}",
    "cancel-in-progress": true
  },
  "jobs": {
    "detect-changes": {
      "name": "Detect CI Scope",
      "runs-on": "ubuntu-latest",
      "outputs": {
        "acceptance": "${{ steps.scope.outputs.acceptance }}",
        "app": "${{ steps.scope.outputs.app }}",
        "hygiene": "${{ steps.scope.outputs.hygiene }}",
        "infra": "${{ steps.scope.outputs.infra }}",
        "selection": "${{ steps.scope.outputs.selection }}"
      },
      "steps": [
        {
          "name": "Checkout exact event revision",
          "uses": "actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803",
          "with": {
            "ref": "${{ github.sha }}",
            "persist-credentials": false,
            "fetch-depth": 0
          }
        },
        {
          "name": "Test CI selection and enforcement",
          "run": "python3 -I -B -m unittest discover -s .github/scripts/ci/tests -v"
        },
        {
          "name": "Resolve complete event scope",
          "id": "scope",
          "env": {
            "CI_BASE_SHA": "${{ github.event.pull_request.base.sha || github.event.before }}",
            "CI_HEAD_SHA": "${{ github.event.pull_request.head.sha || github.sha }}"
          },
          "run": "python3 -I -B .github/scripts/ci/select-checks.py"
        }
      ]
    },
    "e1-acceptance": {
      "name": "E1 Repository Acceptance",
      "needs": "detect-changes",
      "if": "${{ always() && !cancelled() && (needs.detect-changes.result != 'success' || needs.detect-changes.outputs.acceptance != 'false') }}",
      "runs-on": "ubuntu-latest",
      "permissions": {
        "contents": "read"
      },
      "steps": [
        {
          "name": "Checkout exact event revision",
          "uses": "actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803",
          "with": {
            "ref": "${{ github.sha }}",
            "persist-credentials": false,
            "fetch-depth": 0
          }
        },
        {
          "name": "Install verified Terraform",
          "run": "python3 -I -B .github/scripts/ci/install-tools.py terraform"
        },
        {
          "name": "Final E1 repository acceptance",
          "run": "python3 -I -B scripts/tests/final_acceptance/gate.py --report-dir \"$RUNNER_TEMP/e1-acceptance\""
        }
      ]
    },
    "repo-hygiene": {
      "name": "Repo Hygiene",
      "needs": "detect-changes",
      "if": "${{ always() && !cancelled() && (needs.detect-changes.result != 'success' || needs.detect-changes.outputs.hygiene != 'false') }}",
      "permissions": {
        "contents": "read"
      },
      "uses": "./.github/workflows/ci-repo-hygiene.yml"
    },
    "app-ci": {
      "name": "App CI",
      "needs": "detect-changes",
      "if": "${{ always() && !cancelled() && (needs.detect-changes.result != 'success' || needs.detect-changes.outputs.app != 'false') }}",
      "permissions": {
        "contents": "read"
      },
      "uses": "./.github/workflows/ci-dotnet.yml"
    },
    "infra-static": {
      "name": "Infra Static Checks",
      "needs": "detect-changes",
      "if": "${{ always() && !cancelled() && (needs.detect-changes.result != 'success' || needs.detect-changes.outputs.infra != 'false') }}",
      "permissions": {
        "contents": "read"
      },
      "uses": "./.github/workflows/ci-terragrunt.yml",
      "with": {
        "target_env": "dev",
        "aws_region": "us-east-1",
        "run_acceptance": false
      }
    },
    "infra-pr-diagnostics": {
      "name": "PR infrastructure diagnostics (static only, no OIDC)",
      "needs": [
        "detect-changes",
        "infra-static"
      ],
      "if": "${{ github.event_name == 'pull_request' && needs.detect-changes.outputs.infra == 'true' }}",
      "runs-on": "ubuntu-latest",
      "permissions": {},
      "steps": [
        {
          "run": "echo \"Static diagnostics completed. Remote plans require an approved pinned read-only entry on develop/main.\" >> \"$GITHUB_STEP_SUMMARY\""
        }
      ]
    },
    "validation": {
      "name": "${{ github.event_name == 'pull_request' && 'CI Validation' || 'CI Push Validation' }}",
      "needs": [
        "detect-changes",
        "e1-acceptance",
        "repo-hygiene",
        "app-ci",
        "infra-static"
      ],
      "if": "${{ always() }}",
      "runs-on": "ubuntu-latest",
      "permissions": {
        "contents": "read"
      },
      "steps": [
        {
          "name": "Checkout exact event revision",
          "uses": "actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803",
          "with": {
            "ref": "${{ github.sha }}",
            "persist-credentials": false
          }
        },
        {
          "name": "Require actual selected job results",
          "env": {
            "CI_SELECTION": "${{ needs.detect-changes.outputs.selection }}",
            "CI_DETECTION": "${{ needs.detect-changes.result }}",
            "CI_RESULT_ACCEPTANCE": "${{ needs.e1-acceptance.result }}",
            "CI_RESULT_HYGIENE": "${{ needs.repo-hygiene.result }}",
            "CI_RESULT_APP": "${{ needs.app-ci.result }}",
            "CI_RESULT_INFRA": "${{ needs.infra-static.result }}"
          },
          "run": "python3 -I -B .github/scripts/ci/select-checks.py --verify"
        }
      ]
    }
  }
}

