{
  "name": "CD Orchestrator",
  "on": {
    "push": {
      "branches": [
        "develop",
        "main"
      ],
      "paths": [
        "terraform/**",
        "demo-api/**",
        "scripts/**",
        ".github/**",
        "ci/**"
      ]
    }
  },
  "permissions": {
    "contents": "read"
  },
  "concurrency": {
    "group": "e1-CD-Orchestrator-${{ github.ref }}",
    "cancel-in-progress": false
  },
  "jobs": {
    "scope": {
      "uses": "./.github/workflows/cd-scope.yml",
      "permissions": {
        "contents": "read",
        "pull-requests": "read"
      }
    },
    "prepare-dev": {
      "needs": [
        "scope"
      ],
      "if": "${{ github.ref == 'refs/heads/develop' && needs.scope.outputs.critical_manual_only_changed != 'true' && needs.scope.outputs.unmapped_high_risk_paths == '' }}",
      "runs-on": "ubuntu-latest",
      "permissions": {},
      "outputs": {
        "shared": "${{ steps.requests.outputs.shared }}",
        "secrets": "${{ steps.requests.outputs.secrets }}",
        "global": "${{ steps.requests.outputs.global }}",
        "data": "${{ steps.requests.outputs.data }}",
        "platform": "${{ steps.requests.outputs.platform }}",
        "apps": "${{ steps.requests.outputs.apps }}",
        "edge": "${{ steps.requests.outputs.edge }}"
      },
      "steps": [
        {
          "id": "requests",
          "shell": "bash",
          "env": {
            "SAFE": "${{ needs.scope.outputs.safe_layers }}",
            "HIGH": "${{ needs.scope.outputs.high_risk_layers }}",
            "REVISION": "${{ vars.E1_INFRA_DEV_REVISION }}",
            "HIGH_REVISION": "${{ vars.E1_INFRA_HIGH_RISK_DEV_REVISION }}"
          },
          "run": "python3 -I -B - <<'PY'\nimport json,os,uuid\nsafe=os.environ['SAFE'].splitlines();high=os.environ['HIGH'].splitlines()\nassert set(safe)<=set(('shared','secrets','global','platform','edge'))\nassert set(high)<=set(('data','apps/fargate','apps'))\nwith open(os.environ['GITHUB_OUTPUT'],'a') as f:\n    for layer in ('shared','secrets','global','data','platform','apps','edge'):\n        revision=os.environ['HIGH_REVISION'] if layer in ('data','apps') else os.environ['REVISION']\n        value={'operation_id':str(uuid.uuid4()),'operation':'reconcile','layer':layer,'revision':revision,'parameters':{}}\n        f.write(layer+'='+json.dumps(value,separators=(',',':'))+'\\n')\n        if layer in high or (layer=='apps' and 'apps/fargate' in high):print(json.dumps(value,separators=(',',':')))\nPY"
        }
      ]
    },
    "dev-shared": {
      "runs-on": "ubuntu-latest",
      "permissions": {},
      "steps": [
        {
          "run": "echo \"::error::E1 infra-dev is inactive: no verified immutable workflow pin, installation and governance binding.\"; exit 1"
        }
      ],
      "needs": [
        "scope",
        "prepare-dev"
      ],
      "if": "${{ always() && github.ref == 'refs/heads/develop' && needs['prepare-dev'].result == 'success' && contains(needs.scope.outputs.safe_layers, 'shared') }}"
    },
    "dev-secrets": {
      "runs-on": "ubuntu-latest",
      "permissions": {},
      "steps": [
        {
          "run": "echo \"::error::E1 infra-dev is inactive: no verified immutable workflow pin, installation and governance binding.\"; exit 1"
        }
      ],
      "needs": [
        "scope",
        "prepare-dev",
        "dev-shared"
      ],
      "if": "${{ always() && github.ref == 'refs/heads/develop' && needs['prepare-dev'].result == 'success' && contains(needs.scope.outputs.safe_layers, 'secrets') && (needs['dev-shared'].result == 'success' || needs['dev-shared'].result == 'skipped') }}"
    },
    "dev-global": {
      "runs-on": "ubuntu-latest",
      "permissions": {},
      "steps": [
        {
          "run": "echo \"::error::E1 infra-dev is inactive: no verified immutable workflow pin, installation and governance binding.\"; exit 1"
        }
      ],
      "needs": [
        "scope",
        "prepare-dev",
        "dev-shared",
        "dev-secrets"
      ],
      "if": "${{ always() && github.ref == 'refs/heads/develop' && needs['prepare-dev'].result == 'success' && contains(needs.scope.outputs.safe_layers, 'global') && (needs['dev-shared'].result == 'success' || needs['dev-shared'].result == 'skipped') && (needs['dev-secrets'].result == 'success' || needs['dev-secrets'].result == 'skipped') }}"
