"""Observe real ASG/EC2 routing and a bounded private HTTPS probe; never repair."""
import datetime as dt
import hashlib
import json
from storage_observer import require, utc


def control_plane(clients, c):
    groups = clients('autoscaling').describe_auto_scaling_groups(AutoScalingGroupNames=[c['asg']])['AutoScalingGroups']
    require(len(groups) == 1 and groups[0]['AutoScalingGroupName'] == 'demo-dev-asg-nat-a', 'ASG_IDENTITY')
    group = groups[0]
    members = [m for m in group['Instances'] if m['LifecycleState'] == 'InService' and m['HealthStatus'] == 'Healthy']
    evidence = {'asg': group['AutoScalingGroupName'], 'desired': group['DesiredCapacity'], 'healthyMembers': [m['InstanceId'] for m in members]}
    failures = []
    if group['DesiredCapacity'] != 1 or len(members) != 1:
        failures.append('ONE_HEALTHY_NAT_NOT_PRESENT')
    else:
        reservations = clients('ec2').describe_instances(InstanceIds=[members[0]['InstanceId']])['Reservations']
        instances = [i for r in reservations for i in r['Instances']]
        require(len(instances) == 1, 'EC2_IDENTITY')
        i = instances[0]
        evidence.update(instance=i['InstanceId'], state=i['State']['Name'], subnet=i.get('SubnetId'),
                        launchTemplate=members[0].get('LaunchTemplate'), sdc=i.get('SourceDestCheck'), eni=next((x['NetworkInterfaceId'] for x in i.get('NetworkInterfaces', [])), None))
        if i['State']['Name'] != 'running' or i.get('SubnetId') != c['publicSubnet'] or i.get('VpcId') != c['vpc'] or members[0].get('LaunchTemplate', {}).get('LaunchTemplateId') != c['lt'] or str(members[0].get('LaunchTemplate', {}).get('Version')) != '4' or i.get('SourceDestCheck') is not False:
            failures.append('NAT_CONFIGURATION_NOT_RECOVERED')
    routes = clients('ec2').describe_route_tables(RouteTableIds=[c['routeTable']])['RouteTables']
    require(len(routes) == 1 and routes[0]['VpcId'] == c['vpc'], 'ROUTE_TABLE_IDENTITY')
    default = [r for r in routes[0]['Routes'] if r.get('DestinationCidrBlock') == '0.0.0.0/0']
    evidence['defaultRoutes'] = default
    if len(default) != 1 or default[0].get('State') != 'active' or default[0].get('NetworkInterfaceId') != evidence.get('eni'):
        failures.append('PRIVATE_ROUTE_NOT_RECOVERED')
    addresses = clients('ec2').describe_addresses(AllocationIds=[c['allocationId']])['Addresses']
    require(len(addresses) == 1 and addresses[0]['PublicIp'] == c['expectedEip'], 'EIP_IDENTITY')
    evidence['eip'] = {k: addresses[0].get(k) for k in ('AllocationId', 'PublicIp', 'NetworkInterfaceId', 'AssociationId')}
    if addresses[0].get('NetworkInterfaceId') != evidence.get('eni'):
        failures.append('EIP_NOT_RECOVERED')
    return {'verdict': 'Fail' if failures else 'Pass', 'failures': failures, 'evidence': evidence}


def connectivity(clients, c, now, invocation):
    payload = json.dumps({'operation': 'https-egress-a', 'observationId': invocation}).encode()
    result = clients('lambda').invoke(FunctionName=c['probeArn'], InvocationType='RequestResponse', Payload=payload)
    try:
        require(not result.get('FunctionError'), 'PROBE_EXECUTOR_FAILED')
        raw = result['Payload'].read(4097)
    finally:
        if result.get('Payload') is not None:
            result['Payload'].close()
    require(len(raw) <= 4096, 'PROBE_RESPONSE_BOUND')
    probe = json.loads(raw)
    require(probe['observationId'] == invocation and abs((utc(probe['at'])-now).total_seconds()) <= 30 and probe['httpsRequests'] == 1, 'PROBE_CORRELATION')
    require(probe.get('status') in ('HTTPS_SUCCESS', 'HTTPS_FAILED'), 'PROBE_STATUS')
    failed = probe['status'] != 'HTTPS_SUCCESS' or probe.get('egressIp') != c['expectedEip']
    return {'verdict': 'Fail' if failed else 'Pass',
            'failures': ['PRIVATE_HTTPS_EGRESS_FAILED'] if failed else [], 'evidence': {'probe': probe}}


def observe(clients, c, now, invocation):
    require(now < utc(c['expiresAt']), 'NAT_OBSERVER_WINDOW_EXPIRED')
    checks = {}
    for name, call in [('controlPlane', lambda: control_plane(clients, c)),
                       ('connectivity', lambda: connectivity(clients, c, now, invocation))]:
        try:
            checks[name] = call()
        except Exception as error:
            checks[name] = {'verdict': 'Unknown', 'failures': [name.upper() + '_UNAVAILABLE'],
                            'errorType': type(error).__name__, 'evidence': {}}
    control, network = checks['controlPlane'], checks['connectivity']
    # A failed real request is evidence even if an AWS read failed. A missing
    # probe result is never proof of lost connectivity, including a replacement.
    verdict = ('Fail' if network['verdict'] == 'Fail' else
               'Unknown' if 'Unknown' in (control['verdict'], network['verdict']) else
               control['verdict'])
    return {'verdict': verdict, 'checks': checks,
            'failures': control['failures'] + network['failures'],
            'evidence': {**control['evidence'], **network['evidence']}}


def handler(event, context, clients, c):
    now = dt.datetime.now(dt.timezone.utc)
    invocation = event['id']
    try:
        result = observe(clients, c, now, invocation)
    except Exception as error:
        # An unavailable observer is unknown health, never proof of NAT failure.
        result = {'verdict': 'Unknown', 'failures': ['OBSERVER_UNAVAILABLE'], 'errorType': type(error).__name__}
    identity = hashlib.sha256(json.dumps([invocation, result], sort_keys=True).encode()).hexdigest()
    report = {'schemaVersion': 1, 'monitor': 'nat-a-egress', 'producer': 'nat-observer', 'id': identity,
              'resource': 'nat/dev/a', 'generation': 'lt4-e13v6', 'observedAt': now.isoformat(), 'dataAt': now.isoformat(),
              'verdict': result['verdict'], 'assurance': 'Reported', 'runId': invocation,
              'detail': 'AWS control=' + result.get('checks', {}).get('controlPlane', {}).get('verdict', 'Unknown') +
                        '; private HTTPS=' + result.get('checks', {}).get('connectivity', {}).get('verdict', 'Unknown') +
                        '; ' + (','.join(result['failures']) or 'EIP_ROUTE_SDC_HTTPS_VERIFIED')}
    response = clients('events').put_events(Entries=[{'EventBusName': c['bus'], 'Source': 'sentinel.report.nat-observer',
        'DetailType': 'Sentinel Observation v1', 'Detail': json.dumps(report, separators=(',', ':'))}])
    require(response['FailedEntryCount'] == 0, 'NAT_OBSERVATION_DELIVERY_UNCONFIRMED')
    receipt = {'observationId': invocation, 'at': now.isoformat(), 'result': result, 'eventId': response['Entries'][0]['EventId'], 'reportId': identity}
    print(json.dumps(receipt))
    return receipt

files.operations/integrations/portable/trial/r:
terraform {
  required_version = ">= 1.6, < 2.0"
  required_providers {
    aws = { source = "hashicorp/aws", version = ">= 6.28, < 7.0" }
  }
}
variable "config_path" { type = string }
variable "lambda_zip" { type = string }
variable "enabled" {
  type    = bool
  default = false
}
variable "alarm_notices_enabled" {
  type    = bool
  default = false
}
locals {
  config              = jsondecode(file(var.config_path))
  name                = local.config.deployment
  archive_bucket_name = "snt-${lower(local.name)}-${local.config.account}-${local.config.region}"
  roles               = toset(["worker", "ingestion", "watchdog", "cleanup"])
  handlers = {
    worker = "Tick", ingestion = "Ingest", watchdog = "Watchdog", cleanup = "Cleanup"
  }
  schedules      = { worker = "rate(1 minute)", watchdog = "rate(1 minute)", cleanup = "rate(1 minute)" }
  modes          = { worker = "tick", watchdog = "watchdog", cleanup = "cleanup" }
  producers      = toset(flatten([for m in local.config.monitors : m.sources if contains(["report", "sql-backup"], m.kind)]))
  actions        = try(local.config.notificationsEnabled, false) && try(local.config.topicArn, null) != null ? [local.config.topicArn] : []
  archive_prefix = "sentinel/v3/*"
  read_actions = distinct(flatten([for m in local.config.monitors : lookup({
    ec2        = ["ec2:DescribeInstanceStatus"], asg = ["autoscaling:DescribeAutoScalingGroups"],
    alarm      = ["cloudwatch:DescribeAlarms"], aws-backup = ["backup:ListRecoveryPointsByResource"],
    rds-backup = ["rds:DescribeDBInstances"], aurora-backup = ["rds:DescribeDBClusters"]
  }, m.kind, [])]))
}
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
resource "aws_dynamodb_table" "state" {
  name                        = "${local.name}-state"
  billing_mode                = "PAY_PER_REQUEST"
  hash_key                    = "PK"
  range_key                   = "SK"
  deletion_protection_enabled = var.retirement == null
  dynamic "attribute" {
    for_each = toset(["PK", "SK", "DuePK", "DueSK", "ActivePK", "ActiveSK", "CleanPK", "CleanSK"])
    content {
      name = attribute.value
      type = "S"
    }
  }
  dynamic "global_secondary_index" {
    for_each = { Due = "Due", Active = "Active", Cleanup = "Clean" }
    content {
      name            = global_secondary_index.key
      hash_key        = "${global_secondary_index.value}PK"
      range_key       = "${global_secondary_index.value}SK"
      projection_type = "ALL"
    }
  }
  point_in_time_recovery {
    enabled                 = true
    recovery_period_in_days = 1
  }
  server_side_encryption { enabled = true }
  lifecycle {
    precondition {
      condition     = data.aws_caller_identity.current.account_id == local.config.account && data.aws_region.current.region == local.config.region
      error_message = "Provider account/region must match the validated Sentinel manifest."
    }
  }
}
resource "aws_s3_bucket" "archive" {
  bucket        = local.archive_bucket_name
  force_destroy = false
  lifecycle {
    precondition {
      condition = length(local.archive_bucket_name) <= 63 && can(regex("^snt-[a-z0-9][a-z0-9-]*[a-z0-9]$", local.archive_bucket_name)) && alltrue([
        for suffix in ["-s3alias", "--ol-s3", "--x-s3", "--table-s3", "-an"] : !endswith(local.archive_bucket_name, suffix)
      ])
      error_message = "Sentinel archive requires the snt- namespace and a valid shared-namespace S3 name, at most 63 characters; no truncation or legacy bucket fallback."
    }
  }
}
resource "aws_s3_bucket_public_access_block" "archive" {
  bucket                  = aws_s3_bucket.archive.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
resource "aws_s3_bucket_versioning" "archive" {
  bucket = aws_s3_bucket.archive.id
  versioning_configuration { status = "Enabled" }
}


resource "aws_sqs_queue" "dead" {
  for_each                  = toset(["reports", "operations"])
  name                      = "${local.name}-${each.key}-dlq"
  message_retention_seconds = 1209600
  sqs_managed_sse_enabled   = true
}
resource "aws_sqs_queue" "reports" {
  name                       = "${local.name}-reports"
  visibility_timeout_seconds = 360
  message_retention_seconds  = 1209600
  sqs_managed_sse_enabled    = true
  redrive_policy             = jsonencode({ deadLetterTargetArn = aws_sqs_queue.dead["reports"].arn, maxReceiveCount = 5 })
}
resource "aws_cloudwatch_event_bus" "reports" { name = local.name }
resource "aws_cloudwatch_event_rule" "reports" {
  name           = "${local.name}-reports"
  event_bus_name = aws_cloudwatch_event_bus.reports.name
  state          = var.enabled ? "ENABLED" : "DISABLED"
  event_pattern  = jsonencode({ source = [for p in local.producers : "sentinel.report.${p}"], "detail-type" = ["Sentinel Observation v1"], account = [local.config.account], region = [local.config.region] })
  count          = length(local.producers) > 0 ? 1 : 0
}
resource "aws_cloudwatch_event_target" "reports" {
  count          = length(local.producers) > 0 ? 1 : 0
  rule           = aws_cloudwatch_event_rule.reports[0].name
  event_bus_name = aws_cloudwatch_event_bus.reports.name
  arn            = aws_sqs_queue.reports.arn
  dead_letter_config { arn = aws_sqs_queue.dead["operations"].arn }
  retry_policy {
    maximum_event_age_in_seconds = 3600
    maximum_retry_attempts       = 3
  }
}
resource "aws_sqs_queue_policy" "reports" {
  count     = length(local.producers) > 0 ? 1 : 0
  queue_url = aws_sqs_queue.reports.id
  policy    = jsonencode({ Version = "2012-10-17", Statement = length(local.producers) > 0 ? [{ Effect = "Allow", Principal = { Service = "events.amazonaws.com" }, Action = "sqs:SendMessage", Resource = aws_sqs_queue.reports.arn, Condition = { ArnEquals = { "aws:SourceArn" = aws_cloudwatch_event_rule.reports[0].arn } } }] : [] })
}
resource "aws_iam_role" "runtime" {
  for_each             = local.roles
  name                 = "${local.name}-${each.key}"
  permissions_boundary = aws_iam_policy.ecs_boundary[each.key].arn
  tags                 = { Project = local.config.project, Deployment = local.name, ManagedBy = "Terraform", Component = "sentinel-portable" }
  assume_role_policy   = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Principal = { Service = "lambda.amazonaws.com" }, Action = "sts:AssumeRole" }] })
}
resource "aws_cloudwatch_log_group" "runtime" {
  for_each          = local.roles
  name              = "/aws/lambda/${local.name}-${each.key}"
  retention_in_days = 30
}
locals {
  ecs_runtime_policies = { for component in local.roles : component => jsonencode({ Version = "2012-10-17", Statement = concat([
    { Effect = "Allow", Action = ["logs:CreateLogStream", "logs:PutLogEvents"], Resource = "${aws_cloudwatch_log_group.runtime[component].arn}:*" },
    { Effect = "Allow", Action = component == "watchdog" ? ["dynamodb:GetItem"] : ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query", "dynamodb:ConditionCheckItem"], Resource = [aws_dynamodb_table.state.arn, "${aws_dynamodb_table.state.arn}/index/*"] },
    { Effect = "Allow", Action = ["sqs:SendMessage"], Resource = aws_sqs_queue.dead["operations"].arn }
    ], component == "ingestion" ? [
    { Effect = "Allow", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes"], Resource = aws_sqs_queue.reports.arn }
    ] : [], component == "worker" ? [
    { Effect = "Allow", Action = ["s3:PutObject", "s3:GetObject"], Resource = "${aws_s3_bucket.archive.arn}/${local.archive_prefix}" }
    ] : [], component == "worker" ? [local.archive_kms_statement
    ] : [], component == "worker" && length(local.read_actions) > 0 ? [
    { Effect = "Allow", Action = local.read_actions, Resource = "*", Condition = { StringEquals = { "aws:RequestedRegion" = local.config.region } } }
    ] : [], component == "worker" && length([for m in local.config.monitors : m if m.kind == "s3-object"]) > 0 ? [
    { Effect = "Allow", Action = ["s3:GetObject"], Resource = [for m in local.config.monitors : "${m.resource}/${m.selector}" if m.kind == "s3-object"] }
    ] : [], component == "worker" && length(local.actions) > 0 ? [
    { Effect = "Allow", Action = ["sns:Publish"], Resource = local.actions }
    ] : [], component == "worker" && length(local.actions) > 0 ? [local.notice_kms_statement
  ] : []) }) }
}
resource "aws_iam_role_policy" "runtime" {
  for_each = local.roles
  role     = aws_iam_role.runtime[each.key].id
  policy   = local.ecs_runtime_policies[each.key]
}
resource "aws_lambda_function" "runtime" {
  for_each                       = local.roles
  function_name                  = "${local.name}-${each.key}"
  role                           = aws_iam_role.runtime[each.key].arn
  filename                       = var.lambda_zip
  source_code_hash               = filebase64sha256(var.lambda_zip)
  runtime                        = "dotnet10"
  architectures                  = ["x86_64"]
  handler                        = "Ecs.Backup.Portable.Host::Ecs.Backup.Portable.Host.Function::${local.handlers[each.key]}"
  timeout                        = 60
  memory_size                    = 512
  reserved_concurrent_executions = each.key == "ingestion" ? 2 : 1
  publish                        = true
  environment { variables = { SENTINEL_TABLE = aws_dynamodb_table.state.name, SENTINEL_ARCHIVE = aws_s3_bucket.archive.id, SENTINEL_ARCHIVE_KMS_KEY = var.security.archive_kms_key_arn, SENTINEL_QUEUE_ARN = aws_sqs_queue.reports.arn } }
  depends_on = [aws_iam_role_policy.runtime]
}
resource "aws_lambda_alias" "live" {
  for_each         = local.roles
  name             = "live"
  function_name    = aws_lambda_function.runtime[each.key].function_name
  function_version = aws_lambda_function.runtime[each.key].version
}
resource "aws_lambda_event_source_mapping" "reports" {
  event_source_arn        = aws_sqs_queue.reports.arn
  function_name           = aws_lambda_alias.live["ingestion"].arn
  batch_size              = 5
  function_response_types = ["ReportBatchItemFailures"]
  enabled                 = var.enabled
}
resource "aws_cloudwatch_event_rule" "tick" {
  for_each            = local.schedules
  name                = "${local.name}-${each.key}"
  schedule_expression = each.value
  state               = var.enabled ? "ENABLED" : "DISABLED"
}
resource "aws_cloudwatch_event_target" "tick" {
  for_each = local.schedules
  rule     = aws_cloudwatch_event_rule.tick[each.key].name
  arn      = aws_lambda_alias.live[each.key].arn
  input    = jsonencode({ Deployment = local.name, Mode = local.modes[each.key] })
  retry_policy {
    maximum_event_age_in_seconds = 60
    maximum_retry_attempts       = 0
  }
  dead_letter_config { arn = aws_sqs_queue.dead["operations"].arn }
}
# Two serialized asynchronous admissions consume the existing 128/hour profile.
# Each invocation keeps 64 requests/four jobs; concurrency remains one. The same
# fenced journal, exact input and existing rule permission prevent effect races.
variable "worker_admissions_per_tick" {
  type    = number
  default = 1
  validation {
    condition     = contains([1, 2], var.worker_admissions_per_tick)
    error_message = "At most two admissions per minute fit the unchanged 128/hour profile."
  }
}
resource "aws_cloudwatch_event_target" "worker_second" {
  count     = var.worker_admissions_per_tick == 2 ? 1 : 0
  rule      = aws_cloudwatch_event_rule.tick["worker"].name
  target_id = "bounded-second-admission"
  arn       = aws_lambda_alias.live["worker"].arn
  input     = jsonencode({ Deployment = local.name, Mode = "tick" })
  retry_policy {
    maximum_event_age_in_seconds = 60
    maximum_retry_attempts       = 0
  }
  dead_letter_config { arn = aws_sqs_queue.dead["operations"].arn }
}
output "ecs_worker_admission_contract" {
  value = {
    admissions  = 1 + length(aws_cloudwatch_event_target.worker_second)
    concurrency = aws_lambda_function.runtime["worker"].reserved_concurrent_executions
    second_target_is_same_worker = alltrue([for t in aws_cloudwatch_event_target.worker_second :
      t.rule == aws_cloudwatch_event_target.tick["worker"].rule &&
      t.arn == aws_cloudwatch_event_target.tick["worker"].arn &&
      t.input == aws_cloudwatch_event_target.tick["worker"].input &&
    t.retry_policy[0].maximum_retry_attempts == 0])
  }
}
resource "aws_lambda_permission" "tick" {
  for_each       = local.schedules
  action         = "lambda:InvokeFunction"
  function_name  = aws_lambda_function.runtime[each.key].function_name
  qualifier      = aws_lambda_alias.live[each.key].name
  principal      = "events.amazonaws.com"
  source_arn     = aws_cloudwatch_event_rule.tick[each.key].arn
  source_account = local.config.account
}
resource "aws_lambda_function_event_invoke_config" "runtime" {
  for_each                     = local.schedules
  function_name                = aws_lambda_function.runtime[each.key].function_name
  qualifier                    = aws_lambda_alias.live[each.key].name
  maximum_event_age_in_seconds = 60
  maximum_retry_attempts       = 0
  destination_config {
    on_failure { destination = aws_sqs_queue.dead["operations"].arn }
  }
}
resource "aws_sqs_queue_policy" "operations" {
  queue_url = aws_sqs_queue.dead["operations"].id
  policy    = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Principal = { Service = "events.amazonaws.com" }, Action = "sqs:SendMessage", Resource = aws_sqs_queue.dead["operations"].arn, Condition = { ArnEquals = { "aws:SourceArn" = concat([for r in aws_cloudwatch_event_rule.tick : r.arn], aws_cloudwatch_event_rule.reports[*].arn) } } }] })
}
resource "aws_cloudwatch_log_metric_filter" "health" {
  name           = "${local.name}-health"
  log_group_name = aws_cloudwatch_log_group.runtime["watchdog"].name
  pattern        = "[timestamp, request, level, kind = SentinelHealthMetric, health]"
  metric_transformation {
    name      = "Health"
    namespace = "Sentinel/${local.name}"
    value     = "$health"
  }
}
resource "aws_cloudwatch_metric_alarm" "health" {
  alarm_name          = "${local.name}-health"
  namespace           = "Sentinel/${local.name}"
  metric_name         = "Health"
  statistic           = "Minimum"
  period              = 60
  evaluation_periods  = 3
  comparison_operator = "LessThanThreshold"
  threshold           = 1
  treat_missing_data  = "breaching"
  actions_enabled     = var.enabled && var.alarm_notices_enabled
  alarm_actions       = local.actions
  ok_actions          = local.actions
}
resource "aws_cloudwatch_metric_alarm" "dead" {
  for_each            = aws_sqs_queue.dead
  alarm_name          = "${local.name}-${each.key}-dead"
  namespace           = "AWS/SQS"
  metric_name         = "ApproximateNumberOfMessagesVisible"
  dimensions          = { QueueName = each.value.name }
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 1
  comparison_operator = "GreaterThanThreshold"
  threshold           = 0
  treat_missing_data  = "notBreaching"
  actions_enabled     = var.enabled && var.alarm_notices_enabled
  alarm_actions       = local.actions
}
resource "aws_cloudwatch_metric_alarm" "errors" {
  for_each            = local.roles
  alarm_name          = "${local.name}-${each.key}-errors"
  namespace           = "AWS/Lambda"
  metric_name         = "Errors"
  dimensions          = { FunctionName = aws_lambda_function.runtime[each.key].function_name }
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  comparison_operator = "GreaterThanThreshold"
  threshold           = 0
  treat_missing_data  = "notBreaching"
  actions_enabled     = var.enabled && var.alarm_notices_enabled
  alarm_actions       = local.actions
}
output "event_bus_arn" { value = aws_cloudwatch_event_bus.reports.arn }
output "table_name" { value = aws_dynamodb_table.state.name }
output "archive_bucket" { value = aws_s3_bucket.archive.id }
output "producer_policies" {
  description = "Attach each policy only to its authorized producer role; the source is bound to that identity."
  value       = { for producer in local.producers : producer => jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Action = "events:PutEvents", Resource = aws_cloudwatch_event_bus.reports.arn, Condition = { StringEquals = { "events:source" = "sentinel.report.${producer}", "events:detail-type" = "Sentinel Observation v1" } } }] }) }
}

resource "aws_iam_policy" "ecs_boundary" {
  for_each = local.roles
  name     = "${local.name}-${each.key}-boundary"
  policy   = local.ecs_runtime_policies[each.key]
  lifecycle {
    precondition {
      condition     = each.key != "worker" || (data.aws_kms_key.notices.key_manager == "CUSTOMER" && data.aws_kms_key.notices.enabled && data.aws_kms_key.notices.key_spec == "SYMMETRIC_DEFAULT" && data.aws_kms_key.notices.key_usage == "ENCRYPT_DECRYPT" && data.aws_kms_key.notices.aws_account_id == local.config.account && data.aws_kms_key.notices.arn == var.security.notice_kms_key_arn)
      error_message = "DescribeKey must prove the exact enabled same-account customer symmetric notice key."
    }
  }
}

files.operations/integrations/Ecs.Backup.Porta:
using Amazon.DynamoDBv2;
using Amazon.DynamoDBv2.Model;
using Sentinel.Application;
using Sentinel.Core;
using Sentinel.Operations;
using Sentinel.Persistence.DynamoDb;

namespace Ecs.Backup.Portable.Host;

// Read current authoritative W#/O# rows instead of treating the worker's slow,
// multi-invocation sweep as current telemetry. No journal writes or GSI claims.
// Worker uses one consistent query + one transaction of at most 32 Get actions.
// Both requests consume its existing 64-request budget, before the checkpoint.
public sealed class CurrentBacklog(IAmazonDynamoDB ddb,DynamoOptions options) {
 public int Requests {get;private set;}
 public BacklogObservation Read(DateTimeOffset now) {
  Requests++;
  var page=ddb.QueryAsync(new QueryRequest{TableName=options.Table,ConsistentRead=true,Limit=32,
   KeyConditionExpression="PK = :pk AND begins_with(SK,:w)",
   ExpressionAttributeValues=new(){[":pk"]=PhysicalLayout.S(options.Namespace),[":w"]=PhysicalLayout.S("W#")}}).GetAwaiter().GetResult();
  if(page.Items.Count>32)throw new InvalidDataException("Backlog query exceeded bound.");
  List<OutboxEntry> entries=[];var layout=new PhysicalLayout(options);
  List<string> ids=[];
  foreach(var row in page.Items) {
   if(row["PK"].S!=options.Namespace||!row["SK"].S.StartsWith("W#",StringComparison.Ordinal))throw new InvalidDataException("Foreign backlog pointer.");
   ids.Add(PhysicalLayout.Payload<string>(row));
  }
  if(ids.Count>0) {
   if(ids.Distinct(StringComparer.Ordinal).Count()!=ids.Count)throw new InvalidDataException("Duplicate work pointer.");
   Requests++;
   var found=ddb.TransactGetItemsAsync(new TransactGetItemsRequest{TransactItems=ids.Select(id=>new TransactGetItem{Get=new Get{TableName=options.Table,Key=layout.Key(PhysicalLayout.Effect(id))}}).ToList()}).GetAwaiter().GetResult();
   if(found.Responses.Count!=ids.Count)throw new InvalidDataException("Incomplete authoritative backlog read.");
   for(int i=0;i<ids.Count;i++)if(found.Responses[i].Item is {Count:>0} item){var entry=PhysicalLayout.Payload<OutboxEntry>(item);if(entry.Id!=ids[i])throw new InvalidDataException("Backlog identity mismatch.");entries.Add(entry);}
  }
  return Observe(entries,now,page.LastEvaluatedKey is not {Count:>0});
 }
 public static BacklogObservation Observe(IEnumerable<OutboxEntry> entries,DateTimeOffset now,bool complete) {
  var result=BacklogObservation.Empty(now,complete);
  foreach(var e in entries) {
   if(e.Status==OutboxStatus.PermanentFailure){result=result with{Failed=result.Failed+1};continue;}
   var due=e.Status is OutboxStatus.Pending or OutboxStatus.Uncertain or OutboxStatus.RetryableFailure
    ?e.DueAt<=now:e.Status==OutboxStatus.Claimed&&e.LeaseUntil<=now;
   if(!due)continue;
   var at=e.Status==OutboxStatus.Claimed?e.LeaseUntil!.Value:e.DueAt;
   DateTimeOffset? Min(DateTimeOffset? old)=>old is null||at<old?at:old;
   var check=e.Intent?.Kind is EffectKind.ScheduleRecoveryCheck or EffectKind.RequestFunctionalProbe;
   var archive=e.Kind==WorkKind.ArchiveDecision;
   result=result with{Checks=result.Checks+(check?1:0),Archives=result.Archives+(archive?1:0),Effects=result.Effects+(!check&&!archive?1:0),
    OldestDueAt=Min(result.OldestDueAt),OldestCheckAt=check?Min(result.OldestCheckAt):result.OldestCheckAt,
    OldestArchiveAt=archive?Min(result.OldestArchiveAt):result.OldestArchiveAt,
    OldestEffectAt=!check&&!archive?Min(result.OldestEffectAt):result.OldestEffectAt};
  }
  return result;
 }
}

using Sentinel.Core;
using Sentinel.Portable;
using Sentinel.Portable.Aws;
namespace Ecs.Backup.Portable;
public static class ReadableNotice {
 public static (string Subject,string Message) Render(IncidentNotice notice,Installation config,bool syntheticTrial) {
  var monitor=config.Monitors.SingleOrDefault(m=>m.Id==notice.Monitor);
  if(notice.SchemaVersion!=2 || notice.Deployment!=config.Deployment || notice.Consumer!=config.Consumer || monitor is null ||
   notice.Resource!=monitor.Resource || notice.Generation!=monitor.Generation || notice.RequiredAssurance!=monitor.RequiredAssurance ||
   notice.Revision<1 || notice.Epoch<1 || notice.EvaluatedAt.Offset!=TimeSpan.Zero ||
   notice.ConfirmedServiceImpact!=(notice.Condition==NoticeCondition.ConfirmedImpact) ||
   notice.Event is not ("EscalateIncident" or "ResolveIncident") ||
   (notice.Event=="ResolveIncident")!=(notice.Condition==NoticeCondition.ExpectationSatisfied))
    throw new ArgumentException("Notice scope/condition/version mismatch; no formatting or delivery.");
  string Safe(string? value,int max=512){value??="(sin dato)";if(value.Length>max || value.Any(c=>char.IsControl(c)))throw new ArgumentException("Unsafe notice field.");return value;}
  var state=notice.Condition switch {
   NoticeCondition.HealthUnverifiable=>"SALUD NO VERIFICABLE",
   NoticeCondition.ObservedFailure=>"FALLO OBSERVADO",
   NoticeCondition.ExpectationUnmet=>"EXPECTATIVA INCUMPLIDA",
   NoticeCondition.ConfirmedImpact=>"IMPACTO CONFIRMADO",
   NoticeCondition.ExpectationSatisfied=>"RECUPERACIÓN VERIFICADA PARA ESTA EXPECTATIVA",
   _=>throw new ArgumentException("Unknown notice condition.")};
  var mark=syntheticTrial?"PRUEBA SINTÉTICA | ":"";
  var service=monitor.Id=="nat-a-egress"?"Salida privada NAT A":monitor.Kind=="sql-backup"?"Backups SQL":"Observación de "+Safe(monitor.Id);
  var message=$"{mark}ECS · {service}\n\nEstado: {state}\nMonitor: {Safe(notice.Monitor)}\nRecurso: {Safe(notice.Resource)}\nMotivo: {Safe(notice.Summary)}\nGarantía exigida: {notice.RequiredAssurance}\nEvaluación UTC: {notice.EvaluatedAt:O}\nRevisión: {notice.Revision}\n";
  foreach(var reason in notice.Reasons.Take(8))message+=$"- {Safe(reason)}\n";
  message+=$"\nAlcance: {Safe(notice.Deployment)} / {Safe(notice.Consumer)}\nResponsable: {Safe(notice.Owner)}\n";
  message+="No implica una restauración SQL ni salud de la aplicación salvo evidencia explícita del contrato.\nAceptar el aviso en SNS no acredita recepción en inbox. SNS puede duplicar o reordenar avisos.\n";
  message+=$"\nDatos técnicos\nSchemaVersion: 2\nEvent: {Safe(notice.Event)}\nCondition: {notice.Condition}\nAssessment: {Safe(notice.Assessment)}\nState: {Safe(notice.State)}\nConfirmedServiceImpact: {notice.ConfirmedServiceImpact}\nCritical: {notice.Critical}\nGeneration: {Safe(notice.Generation)}\nIncidentId: {Safe(notice.IncidentId,128)}\nEpoch: {notice.Epoch}\nDeliveryId: {Safe(notice.DeliveryId,128)}\nAuditId: {Safe(notice.AuditId,128)}\nAcceptance: SNS_PUBLISH_ONLY_NOT_INBOX_RECEIPT\n";
  var subject=mark+"ECS · "+Safe(notice.Monitor)+": "+(notice.Event=="ResolveIncident"?"expectativa recuperada":"revisar");
  if(message.Length>8192)throw new ArgumentException("Notice too large.");return(subject,message);
 }
}

